mapper.select:
select t.machine_id machineId, t.machine_name machineName, t.machine_code machineCode, t.location_name locationName, t.ma_id maId, t.protocol, t.community_id communityId, t.heartbeat_time heartbeatTime, t.state, t.create_time createTime, t.status_cd statusCd, ma.ma_name maName, mma.attr_id attrId, mma.machine_id machineId1, mma.community_id communityId1, mma.spec_cd specCd, mma.value, mma.status_cd statusCd from monitor_machine t left join monitor_area ma on t.ma_id = ma.ma_id left join monitor_machine_attrs mma on mma.machine_id = t.machine_id where 1 =1 and ma.status_cd = '0' and mma.status_cd = '0'
and t.heartbeat_time= #{heartbeatTime}
and t.protocol= #{protocol}
and t.machine_id= #{machineId}
and t.machine_code like concat('%', #{machineCode}, '%')
and t.location_name like concat('%', #{locationName}, '%')
and t.state= #{state}
and t.ma_id= #{maId}
and t.community_id= #{communityId}
and t.machine_name like concat('%', #{machineName}, '%')
and t.status_cd= #{statusCd}
order by t.create_time desc
limit #{page}, #{row}

select
t.machine_id machineId,
t.machine_name machineName,
t.machine_code machineCode,
t.location_name locationName,
t.ma_id maId,
t.protocol,
t.community_id communityId,
t.heartbeat_time heartbeatTime,
t.state,
t.create_time createTime,
t.status_cd statusCd
from monitor_machine t
where 1 =1

    and t.heartbeat_time= #{heartbeatTime}


    and t.protocol= #{protocol}


    and t.machine_id= #{machineId}


    and t.machine_code like concat('%', #{machineCode}, '%')


    and t.location_name like concat('%', #{locationName}, '%')


    and t.state= #{state}


    and t.ma_id= #{maId}


    and t.community_id= #{communityId}


    and t.machine_name like concat('%', #{machineName}, '%')


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

